// Wandelt die Anhänge (Binärdaten) in Pakete mit bis zu 5 Dokumenten für Nokfi um.
const TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const docs = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!TYPES.includes(bin.mimeType)) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ name: bin.fileName || key, mime: bin.mimeType, data: buffer.toString('base64') });
  }
}
const batches = [];
for (let k = 0; k < docs.length; k += 5) batches.push({ json: { files: docs.slice(k, k + 5) } });
return batches;

// Eine Zeile pro Rechnung, mit den Prüfungen von Nokfi in Spalten.
const rows = [];
for (const item of $input.all()) {
  for (const inv of item.json.invoices || []) {
    rows.push({ json: {
      datei: inv.file_name, aussteller: inv.issuer_name, nif_aussteller: inv.issuer_nif,
      nummer: inv.invoice_number, datum: inv.invoice_date, faellig: inv.due_date,
      netto: inv.base, mwst_satz: inv.vat_rate, mwst: inv.vat_amount, einbehalt: inv.irpf_amount, gesamt: inv.total,
      stimmt: inv.checks.totals_ok ? 'ja' : 'NEIN', nif_gueltig: inv.checks.nif_valid ? 'ja' : 'NEIN',
      hinweise: (inv.warnings || []).map(w => w.message).join(' · ')
    } });
  }
}
return rows;
